using System;
using System.Collections.Generic;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading;

namespace SearchIndexService
{
    public class AuditLogger
    {
        private readonly string _logPath;
        private readonly object _lock = new object();

        public AuditLogger(string logDirectory)
        {
            _logPath = Path.Combine(logDirectory, "audit.log");
            if (!Directory.Exists(logDirectory))
                Directory.CreateDirectory(logDirectory);
        }

        private static string Sanitize(string value)
        {
            if (value == null) return string.Empty;
            var sb = new StringBuilder(value.Length);
            foreach (char c in value)
            {
                // Neutralize newlines and other control characters to prevent log forging (CWE-117)
                if (c == '\r' || c == '\n' || char.IsControl(c) || c == '|')
                    sb.Append(' ');
                else
                    sb.Append(c);
            }
            return sb.ToString();
        }

        public void LogOperation(string operation, string user, int documentCount)
        {
            lock (_lock)
            {
                string entry = $"{DateTime.UtcNow:O}|{Sanitize(user)}|{Sanitize(operation)}|docs={documentCount}";
                File.AppendAllText(_logPath, entry + Environment.NewLine);
            }
        }
    }

    public class IndexSegment
    {
        public int SegmentId { get; set; }
        public int DocumentCount { get; set; }
        public int DeletedCount { get; set; }
        public byte[] Checksum { get; set; }

        public int ActiveDocumentCount => DocumentCount - DeletedCount;
    }

    public class SearchIndex
    {
        private readonly List<IndexSegment> _segments = new List<IndexSegment>();
        private readonly AuditLogger _logger;
        private readonly string _indexName;
        private int _nextSegmentId = 0;

        public SearchIndex(string indexName, AuditLogger logger)
        {
            _indexName = indexName;
            _logger = logger;
        }

        public void AddSegment(int documentCount)
        {
            if (documentCount < 0) throw new ArgumentException("documentCount must be non-negative");
            var segment = new IndexSegment
            {
                SegmentId = Interlocked.Increment(ref _nextSegmentId),
                DocumentCount = documentCount,
                DeletedCount = 0,
                Checksum = ComputeChecksum(documentCount, 0)
            };
            lock (_segments)
            {
                _segments.Add(segment);
            }
        }

        public bool MarkDocumentsDeleted(int segmentId, int count, string requestingUser)
        {
            if (count <= 0) return false;

            lock (_segments)
            {
                var segment = _segments.Find(s => s.SegmentId == segmentId);
                if (segment == null) return false;

                // Validate that cumulative deletions don't exceed document count
                if (segment.DeletedCount + count > segment.DocumentCount) return false;

                segment.DeletedCount += count;
                segment.Checksum = ComputeChecksum(segment.DocumentCount, segment.DeletedCount);

                _logger.LogOperation("DELETE_MARK", requestingUser, count);
                return true;
            }
        }

        /// <summary>
        /// Computes the total allocation size needed for a merge buffer.
        /// Each active document requires 4096 bytes in the merge buffer.
        /// We add a header of 256 bytes per segment being merged.
        /// </summary>
        public long ComputeMergeBufferSize(int[] segmentIds)
        {
            long totalActive = 0;
            long segmentHeaderBytes = 0;

            lock (_segments)
            {
                foreach (int id in segmentIds)
                {
                    var seg = _segments.Find(s => s.SegmentId == id);
                    if (seg == null) continue;

                    int active = seg.ActiveDocumentCount;
                    if (active < 0) continue; // skip corrupted segments
                    totalActive += active;
                    segmentHeaderBytes += 256;
                }
            }

            // Buffer size: header per segment + 4096 bytes per active document
            long bufferSize = segmentHeaderBytes + (totalActive * 4096L);
            return bufferSize;
        }

        /// <summary>
        /// Performs a merge operation on the specified segments.
        /// Allocates a buffer based on computed size and processes documents.
        /// </summary>
        public byte[] MergeSegments(int[] segmentIds, string requestingUser)
        {
            long bufferSize = ComputeMergeBufferSize(segmentIds);

            // Security check: buffer size must be positive and within limits
            if (bufferSize <= 0 || bufferSize > 1024 * 1024 * 1024)
            {
                _logger.LogOperation("MERGE_REJECTED", requestingUser, 0);
                return null;
            }

            _logger.LogOperation("MERGE_START", requestingUser, (int)bufferSize);

            // Allocate and fill the merge buffer
            byte[] buffer = new byte[bufferSize];
            int offset = 0;

            lock (_segments)
            {
                foreach (int id in segmentIds)
                {
                    var seg = _segments.Find(s => s.SegmentId == id);
                    if (seg == null) continue;

                    int active = seg.ActiveDocumentCount;
                    if (active < 0) continue;

                    // Write segment header
                    BitConverter.GetBytes(seg.SegmentId).CopyTo(buffer, offset);
                    BitConverter.GetBytes(active).CopyTo(buffer, offset + 4);
                    offset += 256;

                    // Write placeholder data for each active document
                    for (int i = 0; i < active; i++)
                    {
                        if (offset + 4096 > buffer.Length) break;
                        BitConverter.GetBytes(i).CopyTo(buffer, offset);
                        offset += 4096;
                    }
                }
            }

            _logger.LogOperation("MERGE_COMPLETE", requestingUser, offset);
            return buffer;
        }

        private byte[] ComputeChecksum(int docCount, int deletedCount)
        {
            using (var sha = SHA256.Create())
            {
                byte[] data = BitConverter.GetBytes(docCount)
                    .Concat(BitConverter.GetBytes(deletedCount));
                return sha.ComputeHash(data);
            }
        }
    }

    public static class ByteArrayExtensions
    {
        public static byte[] Concat(this byte[] first, byte[] second)
        {
            byte[] result = new byte[first.Length + second.Length];
            Buffer.BlockCopy(first, 0, result, 0, first.Length);
            Buffer.BlockCopy(second, 0, result, first.Length, second.Length);
            return result;
        }
    }

    class Program
    {
        static void Main(string[] args)
        {
            var logger = new AuditLogger("/var/log/searchindex");
            var index = new SearchIndex("primary", logger);

            index.AddSegment(100);
            index.AddSegment(200);

            index.MarkDocumentsDeleted(1, 50, "admin");

            var merged = index.MergeSegments(new[] { 1, 2 }, "admin");
            Console.WriteLine($"Merged buffer size: {merged?.Length ?? 0}");
        }
    }
}
